#!/usr/bin/env python3
"""Render both hosts from shared policy; --check reports stale generated files."""
import argparse
from pathlib import Path


def outputs(root, work):
    common = (root / "agent-policy/common.md").read_text()
    prose = (root / "claude-shared/prose-rules.md").read_text()
    profiles = [(root, "personal", "claude/CLAUDE.md", "codex/AGENTS.md")]
    if work:
        profiles.append((work, "work", "claude-work/CLAUDE.md", "codex-work/AGENTS.md"))
    for repo, scope, claude, codex in profiles:
        policy = (repo / f"agent-policy/{scope}.md").read_text()
        for host, target in (("claude", claude), ("codex", codex)):
            adapter = (root / f"agent-policy/{host}.md").read_text()
            header = "<!-- Generated by rig/bin/render-agent-policy.py; edit agent-policy sources. -->\n\n"
            yield repo / target, header + "\n\n".join(
                part.strip() for part in (common, policy, adapter, prose)
            ) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument("--work-repo", type=Path)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    stale = []
    for path, content in outputs(args.root, args.work_repo):
        if path.exists() and path.read_text() == content:
            continue
        if args.check:
            stale.append(str(path))
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content)
            print(f"Rendered {path}")
    if stale:
        parser.exit(1, "Stale generated policy:\n" + "\n".join(stale) + "\n")


if __name__ == "__main__":
    main()
